package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.google.gson.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.util.*;
/** Owner-local lifecycle options, distinct from a player update or certificate trust. */
public final class RenewalScreen85 extends MaredScreen {
 private final Screen previous;private String owner,loaded="";private final RenewalService85 service=new RenewalService85();private EditBox root;private boolean enabled=true;private long ttl=86400,margin=900,due;private int left,w,scroll,maxScroll;private final List<Button> buttons=new ArrayList<>();
 public RenewalScreen85(Screen previous,String owner){super(tr("title"));this.previous=previous;this.owner=owner;}
 private static Component tr(String key,Object...args){return Component.translatable("mared.renew85."+key,args);}
 private Button button(String key,int x,int y,int width,Runnable fn){Button b=addRenderableWidget(Button.builder(tr(key),a->fn.run()).bounds(x,y,width,20).build());buttons.add(b);return b;}
 private void collect(){if(root!=null)owner=root.getValue().trim();}
 @Override protected void init(){collect();buttons.clear();w=Math.max(250,Math.min(680,width-24));left=(width-w)/2;root=addRenderableWidget(new EditBox(font,left,34,w,20,tr("owner")));root.setMaxLength(4096);root.setValue(owner);int half=(w-4)/2,third=(w-8)/3;
  button(enabled?"enabled":"disabled",left,58,third,()->{enabled=!enabled;rebuildWidgets();});button("ttl."+ttl,left+third+4,58,third,()->{ttl=ttl==3600?86400:ttl==86400?604800:3600;margin=Math.min(margin,ttl/2);rebuildWidgets();});button("margin",left+2*(third+4),58,third,()->{margin=margin==60?300:margin==300?900:margin==900?1800:60;margin=Math.min(margin,ttl/2);rebuildWidgets();});button("save",left,82,half,()->run("save"));button("refresh",left+half+4,82,half,()->run("status"));
  button("renew",left,height-74,third,()->confirm("renew_confirm","RENEW"));button("repair",left+third+4,height-74,third,()->confirm("repair_confirm","REPAIR"));button("abort",left+2*(third+4),height-74,third,()->confirm("abort_confirm","ABORT"));button("https",left,height-50,w,()->{collect();minecraft.setScreen(new HttpsScreen78(this,owner));});button("back",left,height-26,w,this::onClose);if(!owner.isBlank()&&!service.data().has("config"))run("status");}
 private void run(String action){collect();service.run(owner,action,enabled,ttl,margin);due=System.nanoTime()+3_000_000_000L;}
 private void confirm(String key,String action){collect();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)run(action);},tr("confirm_title"),tr(key)));}
 @Override public void tick(){collect();for(Button b:buttons)b.active=!service.busy();root.setEditable(!service.busy());if(!owner.equals(loaded)&&owner.equals(service.observed())&&service.data().has("config")){var d=service.data().getAsJsonObject("config");enabled=d.get("enabled").getAsString().equals("true");ttl=Long.parseLong(d.get("ttl").getAsString());margin=Long.parseLong(d.get("margin").getAsString());loaded=owner;rebuildWidgets();}if(!service.busy()&&System.nanoTime()>=due&&!owner.isBlank())run("status");}
 @Override public void removed(){collect();}@Override public void onClose(){if(!service.busy())minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){var out=new ArrayList<Component>();out.add(tr("help"));out.add(tr("margin_value",margin/60));if(!service.notice().isEmpty())out.add(tr("notice."+service.notice()));if(!Set.of("IDLE","WORKING","READ").contains(service.result()))out.add(Component.literal(service.result()));if(!owner.equals(service.observed()))return out;var d=service.data();try{out.add(tr("state."+d.get("state").getAsString()));out.add(tr("transaction",d.get("transaction").getAsString()));if(!d.get("code").getAsString().isEmpty()){String code=d.get("code").getAsString();out.add(tr("code."+explain(code)));out.add(Component.literal(code));}long expires=Long.parseLong(d.get("expires").getAsString());if(expires>0)out.add(tr("expires",java.time.Instant.ofEpochMilli(expires).toString()));out.add(tr("certificate."+d.get("certificate").getAsString()));long cert=Long.parseLong(d.get("certificateExpires").getAsString());if(cert>0)out.add(tr("certificate_expires",java.time.Instant.ofEpochMilli(cert).toString()));}catch(Exception ignored){}return out;}
 private static String explain(String code){return switch(code){case "RENEWAL85_UNAPPLIED_RELEASE"->"release";case "RENEWAL85_RETENTION_REQUIRED"->"retention";case "RENEWAL85_TARGET_EXPIRED"->"expired";case "RENEWAL85_POINTER_CONFLICT","RENEWAL85_JOURNAL","RENEWAL85_JOURNAL_CHANGED"->"conflict";case "RENEWAL85_CLOCK_CONFIRM_REQUIRED"->"clock";case "RENEWAL85_OPERATOR_PENDING"->"operator";case "RENEWAL85_UPDATE_BUSY","PUBLICATION83_UPDATE_BUSY"->"busy";default->"generic";};}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);var rows=new ArrayList<net.minecraft.util.FormattedCharSequence>();for(Component line:lines())rows.addAll(font.split(line,w-8));int top=110,bottom=height-80,step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-Math.max(0,bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var row:rows){if(y+step>=top&&y<bottom)g.drawString(font,row,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
}
